function getResult(ranges) {
  const arr = new Array(50000).fill(0);

  for (let [start, end, diff] of ranges) {
    arr[start] += diff;
    // 结束时刻不占用，因此不需要end+1
    arr[end] -= diff;
  }

  // 求解差分数列的前缀和
  let ans = arr[0];
  for (let i = 1; i < arr.length; i++) {
    arr[i] += arr[i - 1];
    ans = Math.max(ans, arr[i]);
  }

  return ans;
}

